def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i in range(12):
            digit = int(isbn[i] if isbn[i] != 'X' else 10)
            total += digit * (13 - i)
        return total % 11

    parts = isbn.split('-')
    isbn_numbers = ''.join(parts)[:-1]

    if calculate_checksum(isbn_numbers) == int(isbn[-1]):
        return "Right"
    else:
        corrected_checksum = str(calculate_checksum(isbn_numbers))
        return isbn[:-1] + corrected_checksum

