def count_passing_ways(n: int, m: int) -> int:
    if n == 1:
        return 1

    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][1] = 1
    dp[0][0] = 1

    for i in range(1, n):
        dp[i][1] = 2

    for j in range(2, m + 1):
        for i in range(1, n):
            dp[i][j] = dp[i - 1][j - 1] + dp[i + 1 if i + 1 < n else 0][j - 1]

    return (dp[n - 1][m] + dp[0][m]) % 1000000007

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    dp = [0] * (n + 1)

    for price, importance in items:
        for j in range(n, price - 1, -1):
            dp[j] = max(dp[j], dp[j - price] + importance)

    return dp[n]

def max_energy(beads):
    n = len(beads)
    beads += beads  # Convert the circular array into a linear one by concatenating it with itself
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i + 1, j):
                energy = beads[i] * beads[k] * beads[j]
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + energy)

    return dp[0][n - 1]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        if i == 0:
            term = str(abs(coeff))
        elif i == 1:
            term = f"{abs(coeff)}x" if abs(coeff) != 1 else "x"
        else:
            term = f"{abs(coeff)}x^{i}" if abs(coeff) != 1 else f"x^{i}"
        if coeff < 0:
            term = "-" + term
        else:
            if terms:
                term = "+" + term
        terms.append(term)
    return "".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping and mapping[e] != o:
            return "Failed"
        mapping[e] = o

    if len(mapping) != len(set(mapping.keys())):
        return "Failed"

    if len(message) != len([char for char in message if char in mapping]):
        return "Failed"

    decoded_message = ''.join(mapping.get(char, char) for char in message)
    return decoded_message

def largest_prime_factor(n: int) -> int:
    def is_prime(num: int) -> bool:
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    for i in range(2, int(n**0.5) + 1):
        if n % i == 0 and is_prime(i):
            return n // i
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    def helper(n, k, x):
        if n < k * x or n == 0:
            return 0
        if k == 1:
            return 1
        return sum(helper(n - i, k - 1, i) for i in range(x, n // k + 1))

    return helper(n, k, x)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]

    if last <= n:
        return 1

    count = 0
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    quotient = y0 // x0
    for a in range(1, quotient + 1):
        if quotient % a == 0:
            b = quotient // a
            if a == b:
                count += 1
            elif gcd(a, b) == 1:
                count += 2
    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    queue = deque([[A, 0]])
    visited = set()

    while queue:
        current, steps = queue.popleft()

        if current == B:
            return steps

        if steps >= 10:
            continue

        for rule in rules:
            source, target = rule
            start = 0
            while start < len(current):
                pos = current.find(source, start)
                if pos == -1:
                    break
                new_str = current[:pos] + target + current[pos + len(source):]
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append([new_str, steps + 1])
                start = pos + 1

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque

    original_number = str(n)
    queue = deque([original_number])
    visited = set([original_number])

    while queue:
        current = queue.popleft()
        for i in range(len(current)):
            d = int(current[i])
            for d_new, _ in rules:
                if d == d_new:
                    for j in range(10):
                        new_number = current[:i] + str(j) + current[i+1:]
                        if new_number not in visited:
                            visited.add(new_number)
                            queue.append(new_number)

    return len(visited)

