        for statement in participant_statements:
            if statement.startswith("The day is"):
                # Ignore statements about the day of the week
                continue
            if liar_count and participant in liar_count:
                # Liars can make false statements
                continue
            if participant == scenario and "is guilty." in statement:
                return True
            if participant != scenario and "is guilty." in statement:
                return False
            if participant == scenario and "is not guilty." in statement:
                return False
            if participant != scenario and "is not guilty." in statement:
                continue
    return True

