    player_score = 0
    opponent_score = 0
    game_over = False

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        if abs(player_score - opponent_score) >= 2 and ((player_score >= system) or (opponent_score >= system)):
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0
            game_over = True

        if game_over and point != ' ':
            scores.append(f"{player_score}:{opponent_score}")
            break

    if not game_over:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

def catalan_number(n: int) -> int:
    if n <= 1:
        return 1
    catalan = [0] * (n + 1)
    catalan[0], catalan[1] = 1, 1
    for i in range(2, n + 1):
        catalan[i] = sum(catalan[j] * catalan[i - j - 1] for j in range(i))
    return catalan[n]

