def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [0]
    for volume in volumes:
        for j in range(V, -1, -1):
            if j >= volume:
                dp.append(max(dp[-1], dp[j - volume] + volume))
            else:
                dp.append(dp[-1])
    return V - max(dp[1:])

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    def comb(n, k):
        if k > n:
            return 0
        num = den = 1
        for i in range(k):
            num = num * (n - i) % MOD
            den = den * (i + 1) % MOD
        return num * pow(den, MOD - 2, MOD) % MOD

    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(n):
        for j in range(m, a[i] - 1, -1):
            dp[j] = (dp[j] + dp[j - a[i]]) % MOD

    return dp[m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key = key.upper()
    ciphertext = ciphertext.upper()
    key_length = len(key)
    plaintext = []

    for i, char in enumerate(ciphertext):
        if char.isalpha():
            key_char = key[i % key_length]
            key_shift = ord(key_char) - ord('A')
            plaintext_char = chr((ord(char) - ord('A') - key_shift) % 26 + ord('A'))
            plaintext.append(plaintext_char)
        else:
            plaintext.append(char)

    return ''.join(plaintext).lower()

