def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Find the peak index where the height increases before and decreases after
    peak = 0
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            peak = i
        else:
            break

    # If the whole list is increasing, we need to remove the last student
    if peak == n - 1:
        return 1

    # Calculate the minimum number of students to remove
    left = peak
    right = n - 1
    min_remove = 0

    # Remove students from the left side
    while left > 0:
        if heights[left] < heights[left - 1]:
            min_remove += 1
            left -= 1
        else:
            break

    # Remove students from the right side
    while right > peak:
        if heights[right] < heights[right - 1]:
            min_remove += 1
            right -= 1
        else:
            break

    # If the peak is not included in the formation, we need to remove one more student
    if peak == 0 or peak == n - 1:
        min_remove += 1

    return min_remove

def min_groups(w, n, prices):
    prices.sort()
    groups = 0
    i = 0
    while i < n:
        if i + 1 < n and prices[i] + prices[i + 1] <= w:
            i += 2
        else:
            i += 1
        groups += 1
    return groups

